 "content": "def transform(grid):
    """Expand a centered 2 into diagonal rays and a period-4 field of 1s."""
    n = len(grid[0])
    centers = [c for c, value in enumerate(grid[0]) if value == 2]
    if len(grid) != 1 or len(centers) != 1 or len(grid[0]) != n:
        raise ValueError("Expected a single-row input with exactly one 2")
    center = centers[0]
    out = [[0 for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in (center - r, center + r):
            if 0 <= c < n:
                out[r][c] = 2
    for r in range(3, n):
        for c in range(n):
            if (c - r - center) % 4 == 0 and out[r][c] == 0:
                out[r][c] = 1
    return out

